using System.Security.Cryptography;
using System.Text;

namespace DotLLM.ChunkReuse.Store;

/// <summary>
/// Store partitions (<see cref="ChunkKey.Create"/>'s <c>namespace</c>). The namespace is hashed into every key, so entries written in
/// one namespace are never hits in another, and an index (whose producer identity is the key of no tokens) saved under one
/// namespace loads empty under another. A server with any API key, or more than one client, uses one namespace per key
/// (<see cref="ForApiKey"/>); a namespace-free store (<see cref="Default"/>) is for single-user local servers only.
/// </summary>
public static class ChunkNamespace
{
    /// <summary>The single-user namespace. It is hashed like any other (an empty length-prefixed string), not skipped.</summary>
    public const string Default = "";

    private const int DigestHexChars = 16;

    /// <summary>Longest valid namespace, in characters (all ASCII, so also in bytes).</summary>
    public const int MaxLength = 64;

    /// <summary>
    /// The one reserved name, <c>default</c>: it stands for <see cref="Default"/> in index file names
    /// (<see cref="ChunkIndex.DefaultPath(string, string, string, string, string)"/>), so no namespace may be called that (else the
    /// default namespace and a namespace named <c>default</c> would share, and clobber, one index file).
    /// </summary>
    public const string ReservedDefaultName = "default";

/// <summary>
/// True when <paramref name="value"/> is a valid namespace: <c>^(|k-[0-9a-f]{16}|[a-z0-9._-]{1,64})$</c> except the reserved
/// <see cref="ReservedDefaultName"/>, i.e. the empty <see cref="Default"/>, a <see cref="ForApiKey"/> value, or 1-64
/// characters of <c>[a-z0-9._-]</c>. Valid namespaces are plain ASCII, so they can go into a key, a file name, a JSON ledger
/// or a log line without escaping, and no two distinct strings encode to the same bytes.
/// </summary>
/// <param name="value">Candidate; null is not valid.</param>
/// <returns>Whether it is valid.</returns>
public static bool IsValid(string? value)
{
    if (value is null || value.Length > MaxLength || value == ReservedDefaultName) return false;
    foreach (char c in value)
        if (c is not ((>= 'a' and <= 'z') or (>= '0' and <= '9') or '.' or '_' or '-')) return false;
    return true; // k-[0-9a-f]{16} is a subset of [a-z0-9._-]{1,64}
}

/// <summary>Throws unless <paramref name="value"/> is a valid namespace (<see cref="IsValid"/>).</summary>
/// <param name="value">Candidate.</param>
/// <param name="paramName">Parameter name reported in the exception.</param>
/// <exception cref="ArgumentNullException"><paramref name="value"/> is null.</exception>
/// <exception cref="ArgumentException"><paramref name="value"/> is not a valid namespace.</exception>
public static void Validate(string value, string paramName = "namespace")
{
    ArgumentNullException.ThrowIfNull(value, paramName);
    if (!IsValid(value))
        throw new ArgumentException(
            $"A chunk namespace is empty, k-<16 hex> or 1-{MaxLength} characters of [a-z0-9._-] other than '{ReservedDefaultName}'; got {value.Length} characters that are not.",
            paramName);
}

    /// <summary>
    /// The namespace of an API key: <c>"k-"</c> + the first 16 lowercase hex characters of SHA-256 over the key's UTF-8 bytes.
    /// It holds a digest, never the key, is stable across processes, and never equals <see cref="Default"/>.
    /// </summary>
    /// <param name="apiKey">The caller's API key; not empty (a caller without a key uses <see cref="Default"/>).</param>
    /// <returns>The namespace, e.g. <c>k-e0dbaa0c6455768b</c>.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="apiKey"/> is null.</exception>
    /// <exception cref="ArgumentException"><paramref name="apiKey"/> is empty.</exception>
    public static string ForApiKey(string apiKey)
    {
        ArgumentException.ThrowIfNullOrEmpty(apiKey);
        Span<byte> digest = stackalloc byte[SHA256.HashSizeInBytes];
        SHA256.HashData(Encoding.UTF8.GetBytes(apiKey), digest);
        return "k-" + Convert.ToHexStringLower(digest[..(DigestHexChars / 2)]);
    }
}

namespace DotLLM.ChunkReuse.Store;

/// <summary>
/// Content-addressed store of encoded chunks. A damaged, foreign or mismatched entry is a miss, never a wrong hit.
/// </summary>
/// <remarks>
/// The store does not check how an entry was computed. Callers must put only K/V that match the key: for the default
/// <see cref="ChunkPositioning.Isolated"/> keys, an isolated <see cref="ChunkEncoder"/> encode at positions <c>0..n-1</c> by the
/// model the key's fingerprint names. A recompute output (K/V conditioned on preceding chunks) put under an isolated key would be
/// accepted by every later reader.
/// </remarks>
public interface IChunkStore
{
    /// <summary>Loads the entry for <paramref name="key"/>.</summary>
    /// <param name="key">Chunk key.</param>
    /// <param name="entry">The entry when found and valid.</param>
    /// <returns>Whether a valid entry exists.</returns>
    bool TryGet(ChunkKey key, out ChunkKvEntry entry);

/// <summary>Stores <paramref name="entry"/> under <paramref name="key"/>; a valid existing entry is kept (same key, same content).</summary>
/// <param name="key">Chunk key.</param>
/// <param name="entry">The entry.</param>
void Put(ChunkKey key, ChunkKvEntry entry);

/// <summary>Whether a valid entry exists for <paramref name="key"/>.</summary>
/// <param name="key">Chunk key.</param>
/// <returns>Whether it exists.</returns>
bool Contains(ChunkKey key);

/// <summary>The keys of the stored entries.</summary>
/// <returns>The keys.</returns>
IEnumerable<ChunkKey> Keys();

    /// <summary>Removes the entry for <paramref name="key"/>; a missing entry is a no-op.</summary>
    /// <param name="key">Chunk key.</param>
    void Evict(ChunkKey key);
}

namespace DotLLM.ChunkReuse.Store;

/// <summary>
/// The store is busy: <see cref="FileChunkStore.Put"/> could not replace an invalid file at the entry's path because another
/// handle holds it (on Windows a mapped file cannot be replaced; nothing was stored, the key stays a miss and a later Put can
/// repair it; on Linux and macOS the rename replaces a held file, so this case does not arise there), or, as <see cref="ChunkStoreLockTimeoutException"/>, a store or index lock was held by another writer for the
/// whole timeout. Either way nothing was written; retrying later is safe.
/// </summary>
/// <remarks>
/// A busy <i>entry</i> is transient and local: <see cref="StoredContextAssembler"/> serves the encoded K/V and leaves the key a
/// miss. A <see cref="ChunkStoreLockTimeoutException"/> is not tolerated that way (another writer kept the store lock past the
/// timeout): the assembler lets it propagate, and callers stop and report "the store is unavailable" (CLI <c>store_busy</c>,
/// server <c>chunk_store_unavailable</c>). Catch this base type to report either.
/// </remarks>
public class ChunkStoreBusyException : IOException
{
    /// <summary>Creates the exception for an entry that could not be replaced.</summary>
    /// <param name="path">The entry path that could not be replaced.</param>
    /// <param name="inner">The rename failure.</param>
    public ChunkStoreBusyException(string path, Exception inner)
        : base($"Chunk store entry '{path}' is invalid and held open by another reader; it was not replaced.", inner)
        => Path = path;

/// <summary>Creates the exception with a custom message (derived types).</summary>
/// <param name="path">The file that was busy.</param>
/// <param name="message">The message.</param>
/// <param name="inner">The underlying failure, or null.</param>
protected ChunkStoreBusyException(string path, string message, Exception? inner)
    : base(message, inner)
    => Path = path;

    /// <summary>The busy file: the entry path that could not be replaced, or the lock file that could not be taken.</summary>
    public string Path { get; }
}

/// <summary>
/// A store lock (<see cref="ChunkIndex.AcquireStoreLock"/>) or an index lock (<see cref="ChunkIndex.AcquireIndexLock(string, string, string, string, string, TimeSpan)"/>)
/// was held by another writer (another process, or another handle in this one) for the whole timeout. Nothing was written.
/// </summary>
public sealed class ChunkStoreLockTimeoutException : ChunkStoreBusyException
{
    /// <summary>Creates the exception.</summary>
    /// <param name="lockPath">The lock file.</param>
    /// <param name="timeout">How long the caller waited.</param>
    /// <param name="inner">The last open failure (sharing violation), or null.</param>
    public ChunkStoreLockTimeoutException(string lockPath, TimeSpan timeout, Exception? inner)
        : base(lockPath, $"The chunk store lock '{lockPath}' is held by another writer (waited {timeout.TotalSeconds:0.###} s).", inner)
        => Timeout = timeout;

    /// <summary>How long the caller waited.</summary>
    public TimeSpan Timeout { get; }
}

namespace DotLLM.ChunkReuse.Store;

/// <summary>Size of a <see cref="FileChunkStore"/>: entries and leftover temp files counted separately.</summary>
/// <param name="Entries">Entry files (<c>.ckv</c> with a well-formed key name; content not validated).</param>
/// <param name="EntryBytes">Bytes of the entry files (<see cref="IChunkStore.TotalBytes"/>).</param>
/// <param name="TempFiles">Store temp files (<c>&lt;key&gt;.&lt;guid&gt;.tmp</c>): writes in flight or left by a crashed writer.</param>
/// <param name="TempBytes">Bytes of the temp files.</param>
public readonly record struct StoreStats(int Entries, long EntryBytes, int TempFiles, long TempBytes);
